{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "금연구역 지정 해제 시 관련단체·지역주민 의견수렴 규정 적용 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "금연구역의 지정 변경 또는 해제에 관한 사항은 제5조제2항과 제5조제3항의 규정을 준용하므로, 지정 해제 시에도 관련단체와 지역주민 의견수렴 규정이 적용된다.",
          "b_ids": "금연:제6조제2항, 금연:제5조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "적용 시 의견수렴이 의무인지 가능한 절차인지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "제5조제2항은 시장이 금연구역을 지정하는 경우 관련단체와 지역주민들의 의견을 수렴할 수 있다고 정하고 있으므로, 의견수렴은 의무가 아니라 가능한 절차(재량)이다.",
          "b_ids": "금연:제5조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
